CREATE TABLE public.subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,paddle_subscription_id text NOT NULL UNIQUE,paddle_customer_id text NOT NULL,product_id text NOT NULL,price_id text NOT NULL,status text NOT NULL,current_period_start timestamptz,current_period_end timestamptz,cancel_at_period_end boolean NOT NULL DEFAULT false,environment text NOT NULL CHECK(environment IN ('sandbox','live')),last_event_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.subscriptions TO authenticated; GRANT ALL ON public.subscriptions TO service_role;
ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY; CREATE POLICY subscriptions_read_own ON public.subscriptions FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE INDEX subscriptions_user_env ON public.subscriptions(user_id,environment);
CREATE TABLE public.billing_settings(environment text PRIMARY KEY CHECK(environment IN ('sandbox','live')),enabled boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.billing_settings TO authenticated; GRANT ALL ON public.billing_settings TO service_role;
ALTER TABLE public.billing_settings ENABLE ROW LEVEL SECURITY; CREATE POLICY billing_settings_read ON public.billing_settings FOR SELECT TO authenticated USING(true); INSERT INTO public.billing_settings VALUES('sandbox',true),('live',false);
CREATE TABLE public.plan_usage(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,operation text NOT NULL CHECK(operation IN ('canvas','evaluate-canvas','generate-infographic','improve-section','transcribe-interview','fill-canvas')),environment text NOT NULL CHECK(environment IN ('sandbox','live')),state text NOT NULL DEFAULT 'reserved' CHECK(state IN ('reserved','completed','failed')),challenge_id uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.plan_usage TO authenticated; GRANT ALL ON public.plan_usage TO service_role;
ALTER TABLE public.plan_usage ENABLE ROW LEVEL SECURITY; CREATE POLICY plan_usage_read_own ON public.plan_usage FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE INDEX plan_usage_month ON public.plan_usage(user_id,environment,operation,created_at);
CREATE TABLE public.payment_events(event_id text PRIMARY KEY,environment text NOT NULL CHECK(environment IN ('sandbox','live')),occurred_at timestamptz NOT NULL);
GRANT ALL ON public.payment_events TO service_role; ALTER TABLE public.payment_events ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.premium_access(p_user uuid,p_environment text DEFAULT 'live') RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_user AND role::text='admin') OR EXISTS(SELECT 1 FROM public.subscriptions WHERE user_id=p_user AND environment=p_environment AND product_id='challenge_canvas_premium' AND price_id='challenge_canvas_premium_monthly' AND ((status IN ('active','trialing','past_due') AND (current_period_end IS NULL OR current_period_end>now())) OR (status='canceled' AND current_period_end>now()))) $$;
REVOKE ALL ON FUNCTION public.premium_access(uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.premium_access(uuid,text) TO service_role;
CREATE FUNCTION public.get_plan_usage(p_environment text DEFAULT 'live') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid:=auth.uid(); counts jsonb; subscription jsonb; active boolean; BEGIN
IF u IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF p_environment NOT IN ('sandbox','live') THEN RAISE EXCEPTION 'Invalid environment'; END IF; active:=public.premium_access(u,p_environment);
SELECT jsonb_build_object('canvases',count(*) FILTER(WHERE operation='canvas'),'evaluations',count(*) FILTER(WHERE operation='evaluate-canvas'),'infographics',count(*) FILTER(WHERE operation='generate-infographic')) INTO counts FROM public.plan_usage WHERE user_id=u AND environment=p_environment AND created_at>=date_trunc('month',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AND (state='completed' OR (state='reserved' AND created_at>now()-interval '30 minutes'));
SELECT jsonb_build_object('status',s.status,'current_period_end',s.current_period_end,'cancel_at_period_end',s.cancel_at_period_end) INTO subscription FROM public.subscriptions s WHERE user_id=u AND environment=p_environment ORDER BY last_event_at DESC LIMIT 1;
RETURN jsonb_build_object('premium',active,'enabled',coalesce((SELECT enabled FROM public.billing_settings WHERE environment=p_environment),false),'usage',counts,'subscription',subscription,'resets_at',(date_trunc('month',now() AT TIME ZONE 'UTC')+interval '1 month') AT TIME ZONE 'UTC'); END $$;
REVOKE ALL ON FUNCTION public.get_plan_usage(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.get_plan_usage(text) TO authenticated,service_role;
CREATE FUNCTION public.reserve_plan_usage(p_user uuid,p_operation text,p_environment text DEFAULT 'live') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ticket uuid; used bigint; enabled boolean; BEGIN
IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'Forbidden'; END IF; IF p_environment NOT IN ('sandbox','live') OR p_operation NOT IN ('evaluate-canvas','generate-infographic','improve-section','transcribe-interview','fill-canvas') THEN RAISE EXCEPTION 'Invalid usage'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(p_user::text||p_environment||p_operation,0)); SELECT b.enabled INTO enabled FROM public.billing_settings b WHERE environment=p_environment;
IF enabled AND NOT public.premium_access(p_user,p_environment) THEN IF p_operation IN ('improve-section','transcribe-interview','fill-canvas') THEN RAISE EXCEPTION 'PREMIUM_REQUIRED'; END IF;
SELECT count(*) INTO used FROM public.plan_usage WHERE user_id=p_user AND environment=p_environment AND operation=p_operation AND created_at>=date_trunc('month',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AND (state='completed' OR (state='reserved' AND created_at>now()-interval '30 minutes')); IF used>=1 THEN RAISE EXCEPTION 'MONTHLY_LIMIT'; END IF; END IF;
INSERT INTO public.plan_usage(user_id,operation,environment) VALUES(p_user,p_operation,p_environment) RETURNING id INTO ticket; RETURN ticket; END $$;
REVOKE ALL ON FUNCTION public.reserve_plan_usage(uuid,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reserve_plan_usage(uuid,text,text) TO service_role;
CREATE FUNCTION public.track_canvas_plan() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE env text:=coalesce(nullif(current_setting('app.payment_environment',true),''),'live'); used bigint; enabled boolean; BEGIN
PERFORM pg_advisory_xact_lock(hashtextextended(NEW.user_id::text||env||'canvas',0)); SELECT b.enabled INTO enabled FROM public.billing_settings b WHERE environment=env;
IF enabled AND NOT public.premium_access(NEW.user_id,env) THEN SELECT count(*) INTO used FROM public.plan_usage WHERE user_id=NEW.user_id AND environment=env AND operation='canvas' AND state='completed' AND created_at>=date_trunc('month',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'; IF used>=1 THEN RAISE EXCEPTION 'MONTHLY_LIMIT'; END IF; END IF;
INSERT INTO public.plan_usage(user_id,operation,environment,state,challenge_id) VALUES(NEW.user_id,'canvas',env,'completed',NEW.id); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.track_canvas_plan() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.track_canvas_plan() TO service_role; CREATE TRIGGER challenge_monthly_plan BEFORE INSERT ON public.challenges FOR EACH ROW EXECUTE FUNCTION public.track_canvas_plan();
INSERT INTO public.plan_usage(user_id,operation,environment,state,challenge_id,created_at) SELECT user_id,'canvas','live','completed',id,created_at FROM public.challenges;
CREATE FUNCTION public.create_plan_canvas(p_title text,p_sections jsonb,p_environment text DEFAULT 'live') RETURNS public.challenges LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result public.challenges; u uuid:=auth.uid(); BEGIN
IF u IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF p_environment NOT IN ('sandbox','live') THEN RAISE EXCEPTION 'Invalid environment'; END IF; IF p_title IS NULL OR length(trim(p_title))=0 OR length(p_title)>500 OR p_sections IS NULL OR jsonb_typeof(p_sections)<>'object' OR octet_length(p_sections::text)>65536 THEN RAISE EXCEPTION 'Invalid canvas'; END IF;
PERFORM set_config('app.payment_environment',p_environment,true); INSERT INTO public.challenges(user_id,title,status,sections) VALUES(u,trim(p_title),'draft',p_sections) RETURNING * INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.create_plan_canvas(text,jsonb,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_plan_canvas(text,jsonb,text) TO authenticated;
CREATE FUNCTION public.apply_subscription_event(p_event_id text,p_environment text,p_occurred_at timestamptz,p_subscription jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'Forbidden'; END IF; INSERT INTO public.payment_events VALUES(p_event_id,p_environment,p_occurred_at) ON CONFLICT DO NOTHING; IF NOT FOUND THEN RETURN; END IF;
INSERT INTO public.subscriptions(user_id,paddle_subscription_id,paddle_customer_id,product_id,price_id,status,current_period_start,current_period_end,cancel_at_period_end,environment,last_event_at) VALUES((p_subscription->>'user_id')::uuid,p_subscription->>'paddle_subscription_id',p_subscription->>'paddle_customer_id',p_subscription->>'product_id',p_subscription->>'price_id',p_subscription->>'status',(p_subscription->>'current_period_start')::timestamptz,(p_subscription->>'current_period_end')::timestamptz,coalesce((p_subscription->>'cancel_at_period_end')::boolean,false),p_environment,p_occurred_at)
ON CONFLICT(paddle_subscription_id) DO UPDATE SET status=EXCLUDED.status,current_period_start=EXCLUDED.current_period_start,current_period_end=coalesce(EXCLUDED.current_period_end,subscriptions.current_period_end),cancel_at_period_end=EXCLUDED.cancel_at_period_end,last_event_at=EXCLUDED.last_event_at,updated_at=now() WHERE subscriptions.environment=EXCLUDED.environment AND subscriptions.user_id=EXCLUDED.user_id AND subscriptions.last_event_at<EXCLUDED.last_event_at; END $$;
REVOKE ALL ON FUNCTION public.apply_subscription_event(text,text,timestamptz,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.apply_subscription_event(text,text,timestamptz,jsonb) TO service_role;